API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the API Gateway container

Container_Boundary(api_gateway, "API Gateway") {
    Component(Envoy Edge Router, "Envoy Edge Router", "Envoy Proxy / Istio", "Enforces regional data residency, rate-limiting, circuit breaking, and mTLS enforcement at the network edge.")
    Component(Routing and mTLS Enforcer, "Routing and mTLS Enforcer", "Istio Service Mesh with SPIFFE IDs", "Routes filtered incoming traffic to microservices using Istio mTLS.")
}

Rel(Envoy Edge Router, Routing and mTLS Enforcer, "Passes filtered traffic for secure microservices routing", "Istio mTLS")

@enduml

